#!/usr/bin/env python3
"""Embed a binary file as a C array header.

    python tools/embed.py build/stub.exe src/stub_blob.h --name g_stub
"""

from __future__ import annotations

import argparse
from pathlib import Path


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("input")
    parser.add_argument("output")
    parser.add_argument("--name", default="g_blob")
    args = parser.parse_args()

    data = Path(args.input).read_bytes()
    name = args.name

    lines = [
        "// generated by tools/embed.py - do not edit",
        "#pragma once",
        "",
        f"static const unsigned char {name}[] = {{",
    ]

    per_line = 20
    for i in range(0, len(data), per_line):
        chunk = data[i : i + per_line]
        lines.append("    " + ", ".join(f"0x{b:02X}" for b in chunk) + ",")

    lines.append("};")
    lines.append(f"static const unsigned long {name}_len = {len(data)}UL;")
    lines.append("")

    Path(args.output).write_text("\n".join(lines), encoding="utf-8")
    print(f"embedded {args.input} ({len(data)} bytes) -> {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
